from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json
base=Path(__file__).parent;out=base/'evidence';font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',22)
im=Image.new('RGB',(1280,400),(12,18,27));d=ImageDraw.Draw(im)
for i,(suffix,label)in enumerate([('before','r1：二值标线几何，不代表实虚'),('after','r2：原图复查，左实线 / 右虚线')]):
 d.text((i*640+8,4),label,font=font,fill='white');im.paste(Image.open(out/'audit_final'/('SC_BT_26_'+suffix+'.jpg')),(i*640,40))
im.save(out/'comparison_BT26.jpg',quality=94)
