rows=''.join(f"<tr><td>{r['video']} / {r['seek']}s</td><td>{r['processing_fps']:.2f}</td><td>{r['preview_new_fps']:.2f}</td><td>{r['road_and_semantic_fps']:.2f}</td><td>{r['detection_fps']:.2f}</td></tr>"for r in perf)
clips=''.join(f'<article><h3>{name}</h3><video controls preload="metadata" src="evidence/r2_final/{file}.mp4"></video><a href="evidence/r2_final/{file}_page.png">实际网页截图</a></article>'for name,file in [('日间道路','SC_BT_30'),('黄昏遮挡','SC_BT2_11'),('夜间道路','SC_YJ_128'),('蓝调高架','SC_YJ2_48'),('路口及循环','SC_BT_55')])
html='''<!doctype html><meta charset="utf-8"><title>M4-05-r2 实测证据</title><style>body{background:#101923;color:#ebf2fa;font:17px Microsoft YaHei,sans-serif;max-width:1300px;margin:auto;padding:24px;line-height:1.8}img,video{max-width:100%;width:100%}a{color:#9ee0ff}table{border-collapse:collapse}td,th{border:1px solid #567;padding:7px 16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}article{background:#1a2b39;padding:14px}h1{margin:0}strong{color:#ffd67d}</style><h1>M4-05-r2 · 真实录像车道证据</h1><p>FPGA断电；仅本地录像。YOLOv8n / YOLOP：RKNN/NPU；实虚、左右边界细化、邻道：CPU图像/几何/短时规则。<strong>虚线≠安全变道，UNKNOWN保留。</strong></p><p><a href="交付说明.md">交付说明</a> · <a href="人工核验与限制.md">人工参考与失败</a> · <a href="evidence/performance.json">性能原始摘要</a> · <a href="evidence/controls/checks.json">网页保护检查</a></p><h2>同一个原生帧，独立核验片段26秒</h2><img src="evidence/comparison_BT26.jpg"><p>不是按时间输出标签。定位只用于抽样，生产分类只读图像。右邻道此帧未知，不自动变道。完整原图、道路/标线掩码与JSON在 <a href="evidence/audit_final/">audit_final</a>；<a href="evidence/final_contact.jpg">全部最终核验前后对照</a>。</p><h2>实际SSH浏览器连续短片</h2><p>直接录制动态网页canvas；保留录制PTS，未插帧或倍帧。转MP4前后帧数核对在<a href="evidence/clip_validation.json">clip_validation.json</a>。短片会出现UNKNOWN，不能只看成功时刻推断整片正确。</p><div class="grid">'''+clips+'''</div><h2>实际更新频率</h2><table><tr><th>素材/起点</th><th>处理fps</th><th>预览新帧fps</th><th>道路/语义Hz</th><th>人车检测fps</th></tr>'''+rows+'''</table><p>道路目标8Hz，预览目标15fps；未达到全场景15。年龄从对应图像在香橙派解码起算，不是摄像头端到端延迟。</p><h2>真实请求与不足</h2><p><a href="evidence/controls/adjacent_review.png">右虚线＋右邻走廊：REVIEW</a> · <a href="evidence/controls/adjacent_review.json">对应记录</a> · <a href="evidence/controls/paused_expired.png">暂停过期</a>。可见总数、序号、方向仍未知；只显示局部走廊下限。夜间/遮挡/路缘仍有漏判和未知，详见失败记录，无人工真值准确率。</p>'''
(base/'查看交付证据.html').write_text(html,encoding='utf-8')
